window.EXPLAINER_SEARCH_INDEX = [{"k":"page","t":"Code map: the central files","u":"code/central-files.html","s":"The repository has about 20,000 tracked files. This page lists the small set of files that do most of the work, each with its line count and a link to the page that explains it.","sec":"Code map","lvl":"","h":["Purpose","The central files","Boot and the headless tour","Core runtime","Tools and extensibility","Delegation and background work","Execution and safety","Protocols and clients","How this list was made","Related pages"]},{"k":"page","t":"Code map: the folder tree","u":"code/index.html","s":"The top two levels of folders of the repository at the pinned commit, with file and line counts.","sec":"Code map","lvl":"","h":["Purpose","The folder tree","How the numbers were measured","Related pages"]},{"k":"page","t":"ACP, SDKs and clients","u":"concepts/acp-sdk-and-clients.html","s":"A client reaches dsh through the ACP server, the SDK wire protocol, or the Web and Desktop connection layer. Each shipped profile mounts the seam for its surface.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: the ACP server exposes a fixed set of session methods","Step 2: the SDK wire protocol is one JSON-RPC message per line","Step 3: the Python SDK launches the same binary; it has no protocol of its own","Step 4: Web and Desktop share one connection carrier","More detail","Where the model route is configured, ACP vs. SDK","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"The agent loop and the session log","u":"concepts/agent-loop-and-session.html","s":"AgentRegistry hands agent creation to the agent-loop factory, which makes one live Agent per session. The Agent runs the turn/step loop and appends each turn and step boundary to the session's append-only event log.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: AgentRegistry delegates creation to the registered factory","Step 2: the agent-loop factory builds a ReactLoopAgent","Step 3: the Agent's turn() loop appends to the session log","More detail","Exact conditions that close a turn","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Approval and human interaction","u":"concepts/approval-and-interaction.html","s":"ctx.approval decides one yes-or-no question per action, logs the ask and the outcome, and fails closed when nobody answers.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: a kind-ask decision reaches ctx.approval.request()","Step 2: the session's policy decides before any answerer runs","Step 3: one answerer claims the request, or passes it on","More detail","What each closed outcome means to the caller","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Jobs, workflows, goals and plan mode","u":"concepts/jobs-workflow-goal-plan.html","s":"Four optional capabilities beside the turn/step loop: background jobs, a workflow script that starts subagents, a durable goal, and plan mode's soft guidance.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: ctx.jobs tracks one producer-owned execution per id","Step 2: a workflow script's agent() calls reach the same subagent seam","Step 3: a goal drives its own next round, only while armed","Step 4: plan mode adds a prompt section; it enforces nothing","More detail","The in-process job registry's own default limits","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"The LLM seam and the system prompt","u":"concepts/llm-and-system-prompt.html","s":"ctx.llm streams one model call through the provider adapter registered for its provider name. Before that call, the agent assembles a system prompt from ordered sections and logs it as session history.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: ctx.llm routes stream() to the adapter registered for one provider name","Step 2: the agent assembles the system prompt before it builds the request","Step 3: the rendered prompt is committed to the session, not sent as a hidden field","Step 4: buildRequest() derives the history and streams the frozen request","More detail","Why the system prompt is a session event, not a request field","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Sandbox and execution","u":"concepts/sandbox-and-execution.html","s":"ctx.sandboxPolicy resolves one file-effect mode per call. Shell and terminal wrap the subprocess; fs checks the path itself.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: ctx.sandboxPolicy.resolve() picks one mode and one root","Step 2: shell and terminal wrap the subprocess argv","Step 3: fs checks the path itself, with no ctx.sandbox call","More detail","The escalation ladder: which modes can widen to which","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Skills","u":"concepts/skills.html","s":"ctx.skills merges ranked providers into one catalog. A session injects that catalog as a system reminder, and the model loads one full skill body on demand with the skill tool.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: a provider registers with ctx.skills, and scans its roots in rank order","Step 2: a session injects the catalog as a system reminder","Step 3: the model loads one full skill with the skill tool","More detail","Invocation policy: four combinations, not one flag","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Subagents and delegation","u":"concepts/subagents-and-delegation.html","s":"A parent agent delegates a task to a child through a named provider on ctx.subagents. Local providers keep a durable child session; others run once.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: startActivation() resolves the named provider, then checks its capabilities","Step 2: method presence on the provider decides local or external","Step 3: the Claude Code provider runs the official SDK, not the host's own CLI","Step 4: tool restriction for a delegated scope","More detail","The four start-time capabilities a provider can declare","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Tools and MCP servers","u":"concepts/tools-and-mcp.html","s":"A first-party plugin and an MCP client both register tools into ctx.tools. Each call then goes through the same three-stage pipeline, between durable tool/call and tool/result session events.","sec":"DeepSeek Harness concepts","lvl":"Intermediate","h":["The idea","The picture","In the code","Step 1: registration, from a first-party plugin or an MCP client","Step 2: the fixed pipeline order","Step 3: pre-execute decides allow, deny, cancel, or ask","Step 4: post-execute can accept, replace, or block the result","Step 5: try it yourself","More detail","The four pre-execute decisions, on the wire","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"DeepSeek Harness Explained","u":"index.html","s":"DeepSeek Harness (dsh) is an open-source, everything-is-a-plugin agent harness. This site gives an overview of how one task flows through it, at commit ce7073d5.","sec":"Home","lvl":"","h":["The system map","Start here","How to use this site","The code version this site explains"]},{"k":"page","t":"Everything is a plugin: Cordis","u":"learn/plugins-and-cordis.html","s":"DeepSeek Harness is built on Cordis, a plugin framework. Plugins contribute services, typed events and reversible effects to a shared context.","sec":"Learn the basics","lvl":"Beginner","h":["The idea","The picture","In DeepSeek Harness","More detail","The five dispatch modes, compared","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Profiles and bundles: how a running dsh tree is assembled","u":"learn/profiles-and-bundles.html","s":"A dsh profile stacks named bundles, then patch files overlay the result. This page shows the layers, in order, with two named profiles as examples.","sec":"Learn the basics","lvl":"Beginner","h":["The idea","The picture","In DeepSeek Harness","More detail","The four patch layers, in applied order","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Turn, step, round: the session vocabulary","u":"learn/session-and-loop-vocabulary.html","s":"A session counts its own work with four words: turn, step, round and exchange. The agent loop appends each turn and step boundary to the session log.","sec":"Learn the basics","lvl":"Beginner","h":["The idea","The picture","In DeepSeek Harness","More detail","Each word, defined in the docs and confirmed in code","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"\"Reference: config and environment variables\"","u":"reference/config-and-env.html","s":"The environment variables a reader meets most often, how config files layer, and the main dsh command-line flags, with pointers to the repository's own generated catalogs.","sec":"Reference","lvl":"","h":["Purpose","Main environment variables","Config-file layering","Main CLI flags","Related pages"]},{"k":"page","t":"Life of a headless task","u":"tours/life-of-a-headless-task.html","s":"Follow one dsh --profile headless \"task\" run from the command line to the printed answer, stop by stop.","sec":"Guided tour","lvl":"Intermediate","h":["The idea","The picture","1bin.ts and args.ts parse the command line","2profile-boot.ts composes and boots the profile","3The headless bundle mounts its two plugins","4AgentRegistry creates the Agent","5The task is submitted with agent.followup()","6The turn/step loop drives the model","7Tool calls run through the tool pipeline","8The runner waits for idle, and for any subagents","9The session flushes, and the result reaches stdout","More detail","Exactly when does the wait loop at stop 8 stop?","What can go wrong","Check yourself","Related pages"]},{"k":"page","t":"Glossary","u":"reference/glossary.html","s":"Short definitions of every technical term on this site, with links to the pages that explain them.","sec":"Reference","lvl":"","h":["A","B","C","E","G","J","M","P","R","S","T","W"]},{"k":"term","t":"ACP","u":"reference/glossary.html#term-acp","s":"Agent Client Protocol. The automation-only JSON-RPC-over-stdio protocol the dsh-acp server implements.","a":["Agent Client Protocol"]},{"k":"term","t":"Agent","u":"reference/glossary.html#term-agent","s":"The live object that drives one session: it owns the turn/step loop and the inbox of pending input.","a":[]},{"k":"term","t":"agent loop","u":"reference/glossary.html#term-agent-loop","s":"The turn/step cycle that claims input, calls the model, runs the tools it asks for, and repeats.","a":[]},{"k":"term","t":"approval policy","u":"reference/glossary.html#term-approval-policy","s":"The human-in-the-loop decision for one action: may this specific action proceed?","a":["approval"]},{"k":"term","t":"bundle","u":"reference/glossary.html#term-bundle","s":"A distribution format for Cordis config rows and the code they mount, so whatever it inserts stays patchable by the layers above it.","a":[]},{"k":"term","t":"capability seam","u":"reference/glossary.html#term-capability-seam","s":"A swappable capability with three roles: a Service Definition, one or more Service Providers, and one or more Consumers.","a":["seam"]},{"k":"term","t":"context","u":"reference/glossary.html#term-context","s":"A repository of services. A plugin reads another plugin's service through the context instead of importing it directly.","a":["ctx"]},{"k":"term","t":"Cordis","u":"reference/glossary.html#term-cordis","s":"The vendored plugin framework under dsh. Plugins contribute services, typed events and reversible effects to a shared context.","a":["cordis framework"]},{"k":"term","t":"effect","u":"reference/glossary.html#term-effect","s":"A reversible registration a plugin makes on a context, made with ctx.effect() or ctx.on(). It unwinds on its own when the plugin unloads or reloads.","a":["reversible effect","ctx.effect"]},{"k":"term","t":"exchange","u":"reference/glossary.html#term-exchange","s":"Consecutive turns from a turn whose first step admits human input until the next such turn.","a":[]},{"k":"term","t":"goal","u":"reference/glossary.html#term-goal","s":"One durable completion objective attached to a session, with an active/paused/blocked/complete phase and a goal-round cap.","a":[]},{"k":"term","t":"job","u":"reference/glossary.html#term-job","s":"A long-running background unit tracked by ctx.jobs, with a status of running, stopping, completed, killed or failed.","a":["background job"]},{"k":"term","t":"MCP","u":"reference/glossary.html#term-mcp","s":"Model Context Protocol. It connects the model to tools and resources supplied by external servers.","a":["Model Context Protocol"]},{"k":"term","t":"plan mode","u":"reference/glossary.html#term-plan-mode","s":"Logged per-agent collaboration state that adds a guidance section to each model request while active. It is soft guidance only.","a":[]},{"k":"term","t":"plugin","u":"reference/glossary.html#term-plugin","s":"An object that implements Service: a function with optional inject and apply(ctx) fields, or a Service subclass Cordis mounts into a context.","a":[]},{"k":"term","t":"profile","u":"reference/glossary.html#term-profile","s":"A named plugin-tree composition stored in the Harness home. It lists the bundles it stacks and the user's own patch file.","a":[]},{"k":"term","t":"provider adapter","u":"reference/glossary.html#term-provider-adapter","s":"An LlmAdapter object that streams model calls for one or more provider names. A plugin registers it with ctx.llm.registerAdapter().","a":["LLM adapter","adapter"]},{"k":"term","t":"round","u":"reference/glossary.html#term-round","s":"An outer policy iteration containing a turn, such as a goal round. Round counters belong to that policy, not to every turn.","a":[]},{"k":"term","t":"sandbox","u":"reference/glossary.html#term-sandbox","s":"The process-sandbox seam. It wraps a subprocess in a file-effect policy: read-only, workspace-write, or danger-full-access.","a":[]},{"k":"term","t":"sandbox escalation","u":"reference/glossary.html#term-sandbox-escalation","s":"A one-shot retry of a denied call at a strictly wider sandbox mode. It runs only after an approval answerer allows it.","a":[]},{"k":"term","t":"SDK wire protocol","u":"reference/glossary.html#term-sdk-wire-protocol","s":"The own newline-delimited JSON-RPC protocol of dsh, with one message per line. dsh-sdk-jsonrpc-server serves it over stdio. The TypeScript and Python SDKs speak it.","a":["SDK protocol"]},{"k":"term","t":"service","u":"reference/glossary.html#term-service","s":"What a plugin claims from a context: a stable ctx.<key> such as ctx.tools or ctx.llm, found by key instead of by import.","a":["ctx key"]},{"k":"term","t":"session","u":"reference/glossary.html#term-session","s":"The durable conversation object: one Session holds one append-only event log and is the identity an agent runs on.","a":[]},{"k":"term","t":"session log","u":"reference/glossary.html#term-session-log","s":"The append-only log of SessionEvent records. It is the source of the context the model sees.","a":["event log","SessionEvent log"]},{"k":"term","t":"skill","u":"reference/glossary.html#term-skill","s":"An optional, loadable instruction set, discovered through a provider registry under ctx.skills. Not a session event.","a":[]},{"k":"term","t":"step","u":"reference/glossary.html#term-step","s":"One model request plus the tool executions caused by its response. A turn contains zero or more steps.","a":[]},{"k":"term","t":"subagent","u":"reference/glossary.html#term-subagent","s":"A child agent a parent delegates work to through a named provider. A local child keeps a durable session; others execute once.","a":["child agent"]},{"k":"term","t":"subagent provider","u":"reference/glossary.html#term-subagent-provider","s":"A named backend registered on ctx.subagents. A caller picks one by name. Providers differ in whether the child keeps a session.","a":["provider"]},{"k":"term","t":"system prompt","u":"reference/glossary.html#term-system-prompt","s":"The instruction text for one step. Assembly joins the visible prompt sections in ascending order.","a":[]},{"k":"term","t":"tool call","u":"reference/glossary.html#term-tool-call","s":"One request from the model to run a tool, carried through the tools/pre-execute, tools/execute and tools/post-execute pipeline.","a":["tool execution"]},{"k":"term","t":"tool restriction","u":"reference/glossary.html#term-tool-restriction","s":"An allow or deny name list (or both) on the global tools that one scoped agent can see. ctx.tools.restrict() applies it.","a":[]},{"k":"term","t":"turn","u":"reference/glossary.html#term-turn","s":"One drain of admitted input in a session. It opens before its first input is claimed and closes once nothing is owed.","a":[]},{"k":"term","t":"typed event","u":"reference/glossary.html#term-typed-event","s":"A named extension point a service declares, dispatched as emit, waterfall, parallel, serial or bail, depending on how its listeners must run.","a":["event","cordis event"]},{"k":"term","t":"workflow","u":"reference/glossary.html#term-workflow","s":"An optional capability that lets an agent run a model-written script that starts subagents. It is not part of the agent loop.","a":[]}];
